/**
 * Budget guard for the ungated Bash dispatcher (#3430 / #3438)
 *
 * Removing the if-gate from hooks.json means sync-bash-dispatcher now runs on
 * EVERY Bash call instead of the 13 command prefixes the gate admitted. That is
 * required for correctness — a deny-by-default allowlist is defeated by any
 * enumeration, since whatever is not listed is never evaluated — but it moves
 * the dispatcher onto the hot path.
 *
 * Measured before shipping (macOS, warm): ~47.9 ms per invocation end to end,
 * of which ~33.6 ms is bare node startup. The repo's PreToolUse budget is 50 ms
 * (.claude/rules/hooks-development.md), so the process spawn dominates and the
 * headroom is thin.
 *
 * This test does NOT measure process spawn — it cannot, and CI runners vary too
 * much for a wall-clock assertion to be anything but flaky. It measures the part
 * this change actually controls: the in-process cost of the dispatcher's own
 * member chain on a benign command. If someone later adds an expensive member,
 * or gives restrict-bash a guard that is not O(1), this fails loudly instead of
 * quietly eating the remaining budget.
 */

import { describe, test, expect } from 'vitest';
import type { HookInput } from '../../types.js';
import { syncBashDispatcher } from '../../pretool/bash/sync-bash-dispatcher.js';

function benign(): HookInput {
  return {
    tool_name: 'Bash',
    tool_input: { command: 'echo hello' },
  } as unknown as HookInput;
}

describe('ungated dispatcher — in-process budget', () => {
  test('benign main-thread command costs well under the in-process allowance', () => {
    // Warm up so the first-call JIT cost is not attributed to the measurement.
    for (let i = 0; i < 20; i++) syncBashDispatcher(benign());

    const ITERATIONS = 200;
    const start = performance.now();
    for (let i = 0; i < ITERATIONS; i++) syncBashDispatcher(benign());
    const perCall = (performance.now() - start) / ITERATIONS;

    // 5 ms is deliberately loose: the real constraint is the ~34 ms node spawn,
    // so anything comfortably below this leaves the 50 ms budget intact. A
    // regression that matters (file I/O in a member, a non-O(1) guard) blows
    // through it by orders of magnitude, which is what we want to catch.
    expect(perCall).toBeLessThan(5);
  });

  test('restrict-bash adds no measurable cost to the main-thread path', () => {
    // The self-scoping guard must be one Set lookup on a payload with no
    // agent_type. This asserts the common path stays free rather than trusting
    // that it does.
    const input = benign();
    for (let i = 0; i < 20; i++) syncBashDispatcher(input);

    const start = performance.now();
    for (let i = 0; i < 500; i++) syncBashDispatcher(input);
    const perCall = (performance.now() - start) / 500;

    expect(perCall).toBeLessThan(5);
  });
});
